import{_ as a,o as s,c as o,a2 as n}from"./chunks/framework.DR-IerZT.js";const u=JSON.parse('{"title":"Journal de modernisation","description":"","frontmatter":{"title":"Journal de modernisation","outline":[2,3]},"headers":[],"relativePath":"modernisation/changelog.md","filePath":"modernisation/changelog.md"}'),t={name:"modernisation/changelog.md"};function i(r,e,c,d,l,g){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="journal-de-modernisation" tabindex="-1">Journal de modernisation <a class="header-anchor" href="#journal-de-modernisation" aria-label="Permalink to &quot;Journal de modernisation&quot;">​</a></h1><div class="changelog"><div class="changelog-entry"><div class="changelog-date">2026-10-07</div><div class="changelog-title">Corrections post-conformité Catégories (86 → 98)</div><div class="changelog-tags"><span class="badge badge-done">Approuvé</span> <span class="section-label api">API</span> <span class="section-label front">Frontend</span> <span class="badge badge-spec">Conformité 98/100</span></div><div class="changelog-content"><p>Traitement des 16 issues du rapport de conformité V1 (7 moyennes, 9 basses) puis génération du rapport V2 : 9 corrigées, 4 partiellement corrigées (maintenues en basse), 3 choix assumés liés à la future feature Authentification. Score <strong>86 → 98/100</strong>, décision <strong>Approuvé</strong> (0 critique, 0 élevée, 0 moyenne, 4 basses).</p><ul><li>Format d&#39;erreur standardisé pour les 404/405 de routage (<code>ExceptionSubscriber</code>, header <code>Allow</code>, réponse <code>MethodNotAllowed</code> dans OpenAPI) — issue #13.</li><li><code>declare(strict_types=1)</code> généralisé côté backend (#1), services <code>readonly</code> (#6), tests de bord move/delete validés par mutations (#2) : <strong>217 tests PHPUnit</strong>, 641 assertions.</li><li>Parent du formulaire migré vers le <code>Select</code> Shadcn (#15) ; composants découpés (#7), confirmation du reset (#14).</li><li>Couverture frontend mesurée (<code>@vitest/coverage-v8</code>, seuils 80 %) : <strong>98,69 %</strong> lignes, 93,33 % branches, 96,61 % fonctions, 97,37 % instructions — <strong>171 tests Vitest</strong> (#3).</li><li>Accessibilité et responsive (#16) : focus restitué à la fermeture des dialogues, débordement mobile du tableau admin corrigé à 320 px (colonnes masquées progressivement), captures 320/768/1280 px.</li></ul><p><a href="./categories">Timeline</a> · <a href="./api/categories#corrections-post-conformite-v1-2026-10-07">Corrections API</a> · <a href="./frontend/categories#corrections-post-conformite-v1-2026-10-07">Corrections Frontend</a> · <a href="./conformity-categories">Rapport de conformité</a></p></div></div><div class="changelog-entry"><div class="changelog-date">2026-10-07</div><div class="changelog-title">Migration de la feature Catégories</div><div class="changelog-tags"><span class="badge badge-done">Terminée</span> <span class="section-label api">API</span> <span class="section-label front">Frontend</span> <span class="badge badge-spec">Conformité 86/100</span></div><div class="changelog-content"><p>Exécution de <code>/mod-migrate-feature Categories</code> : spécification détaillée (<code>Categories_spec.md</code>, décisions D-01 à D-10), planification (23 tâches backend, 12 tâches frontend), implémentation Test First et rapport de conformité V1.</p><ul><li>Backend Symfony 7.4 : entités <code>User</code> (socle minimal) et <code>Category</code>, firewall JWT <code>api</code>, 8 routes (<code>/api/categories/*</code>, <code>/api/admin/categories/*</code>), <strong>195 tests PHPUnit</strong> verts.</li><li>Frontend React 19 : page publique <code>/categories</code>, écrans admin liste / création / édition, accès admin par jeton, <strong>135 tests Vitest</strong> verts ; couverture non mesurée (<code>@vitest/coverage-v8</code> absent).</li><li>Conformité : <strong>86/100</strong>, approuvé avec conditions (0 critique, 0 élevée, 7 moyennes, 9 basses).</li></ul><p><a href="./categories">Timeline</a> · <a href="./api/categories">Analyse API</a> · <a href="./frontend/categories">Analyse Frontend</a> · <a href="./conformity-categories">Rapport de conformité</a></p></div></div><div class="changelog-entry"><div class="changelog-date">2026-10-07</div><div class="changelog-title">Installation des stacks cibles</div><div class="changelog-tags"><span class="badge badge-done">Terminée</span> <span class="badge badge-todo">Infrastructure</span></div><div class="changelog-content"><p>Installation via <code>/dev/install-stack</code> des projets cibles : <code>api-rest-symfony-target/</code> (PHP 8.2, Symfony 7.4, PostgreSQL, Docker Compose) et <code>app-react-target/</code> (React 19, TypeScript, Vite, Tailwind CSS 4).</p></div></div><div class="changelog-entry"><div class="changelog-date">2026-10-07</div><div class="changelog-title">Analyse du legacy</div><div class="changelog-tags"><span class="badge badge-done">Terminée</span> <span class="badge badge-todo">Analyse</span></div><div class="changelog-content"><p>Exécution de <code>/mod-analyze-legacy</code> : analyse technique (7 documents), inventaire fonctionnel de <strong>15 features</strong>, 3 rôles et 7 flux, audit de l&#39;inventaire, puis visualisations interactives (arbre fonctionnel, graphe de dépendances).</p><p><a href="/claude-code-ecosystem/exemple-wiki-legacy/docs/analyses/">Analyses techniques</a> · <a href="/claude-code-ecosystem/exemple-wiki-legacy/docs/features/">Spécifications</a> · <a href="/claude-code-ecosystem/exemple-wiki-legacy/mapping/">Cartographie</a></p></div></div></div>',2)])])}const m=a(t,[["render",i]]);export{u as __pageData,m as default};
